CREATE POLICY "authz_insert" ON "fm"."folders" FOR INSERT TO fm_app
  WITH CHECK (((SELECT authz_int.scope_cmd('fm.folders', 'insert')) AND (coalesce("folders"."owner_id" = (SELECT authz.uid()), false)
    AND (coalesce((parent_id is null), false)
