-- fm.files update object_key after (line 69): {object_key IN (SELECT v.object_key FROM fm.file_versions v WHERE v.file_id = files.id AND v.ready)}
-- checked on the row after the change, for roles that row-level security applies to
CREATE OR REPLACE FUNCTION authz_int."file__update_5"() RETURNS trigger
LANGUAGE plpgsql SET search_path FROM CURRENT AS $f$
DECLARE v_lines text;
BEGIN
  IF pg_catalog.row_security_active(TG_RELID)
     AND NOT coalesce((SELECT authz_gen."file__check_6fce862cc9"(ROW("files".*)::"fm"."files") FROM (SELECT NEW.*) AS "files"), false) THEN
    BEGIN
      v_lines := (SELECT string_agg(l, E'\n') FROM authz_gen."fm.files:column_5:why"(NEW) l);
    EXCEPTION WHEN OTHERS THEN
      v_lines := 'no explanation: ' || SQLERRM;
    END;
    RAISE EXCEPTION 'changing object_key of fm.files % needs: {object_key IN (SELECT v.object_key FROM fm.file_versions v WHERE v.file_id = files.id AND v.ready)}', OLD."id" USING ERRCODE = 'insufficient_privilege', DETAIL = v_lines,
      SCHEMA = 'fm', TABLE = 'files', CONSTRAINT = 'authz_update', HINT = 'rowfence help AZ709';
  END IF;
  RETURN NEW;
END $f$;

